fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 0);
        host::display::state_set(2, 0);
        host::display::state_set(3, 0);
        host::display::state_set(5, 0);
        host::display::state_set(6, 1);
        host::display::state_set(7, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(4) == 0;
    host::display::state_set(4, down);
    let round: i32 = host::display::state_get(1);
    let total: i32 = host::display::state_get(2);
    if host::display::state_get(3) == 1 {
        host::display::clear(0x101018);
        host::display::draw_string(170, 150, "FINAL SCORE", 0x808080, 2);
        host::display::draw_number(210, 190, total, 0xffffff, 5);
        match total {
            400..=500 => {
                host::display::draw_string(150, 280, "SHARPSHOOTER", 0x00ff88, 3);
            }
            250..400 => {
                host::display::draw_string(200, 280, "SOLID", 0xffaa00, 3);
            }
            _ => {
                host::display::draw_string(130, 280, "PRACTICE MORE", 0xff4040, 3);
            }
        }
        host::display::draw_string(150, 350, "TAP TO GO AGAIN", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut pos: i32 = host::display::state_get(5);
        let mut dir: i32 = host::display::state_get(6);
        let speed: i32 = 5 + round * 2;
        pos = pos + dir * speed;
        if pos < 0 { pos = 0; dir = 1; }
        if pos > w - 8 { pos = w - 8; dir = -1; }
        host::display::state_set(5, pos);
        host::display::state_set(6, dir);
        if tap {
            let mut dist: i32 = pos + 4 - w / 2;
            if dist < 0 { dist = -dist; }
            let mut pts: i32 = 50 - dist;
            if pts < 0 { pts = 0; }
            pts = pts * 2;
            host::display::state_set(2, total + pts);
            host::display::state_set(7, pts);
            host::display::state_set(1, round + 1);
            if round + 1 >= 5 { host::display::state_set(3, 1); }
        }
        host::display::clear(0x000000);
        host::display::draw_string(8, 10, "ROUND", 0x808080, 2);
        host::display::draw_number(110, 10, round + 1, 0xffffff, 2);
        host::display::draw_string(150, 10, "OF 5", 0x808080, 2);
        host::display::draw_string(8, 40, "LAST", 0x808080, 1);
        host::display::draw_number(50, 40, host::display::state_get(7), 0x00ff88, 1);
        host::display::draw_string(100, 40, "TOTAL", 0x808080, 1);
        host::display::draw_number(150, 40, total, 0xffffff, 1);
        host::display::fill_rect(w / 2 - 24, h / 2 - 30, 48, 60, 0x104020);
        host::display::fill_rect(w / 2 - 2, h / 2 - 30, 4, 60, 0x00ff88);
        host::display::fill_rect(0, h / 2 - 2, w, 4, 0x303030);
        host::display::fill_rect(pos, h / 2 - 24, 8, 48, 0xffffff);
        host::display::draw_string(120, h - 60, "TAP TO STOP THE BAR", 0x808080, 2);
    }
    host::display::present();
}
